var t={en:`Orders no longer consults Catalog. Catalog calls the PSP, while Identity edits unrelated tables. Repair ownership without turning the monolith into microservices.`,ua:`Orders більше не звертається до Catalog. Catalog викликає платіжний провайдер, а Identity редагує чужі таблиці. Виправ відповідальність без переходу до мікросервісів.`};var n={en:[`Remove inappropriate Catalog→provider and Identity→db edges.`,`Restore the Orders→Catalog business contract.`,`Explain module-owned tables even in a shared physical database.`],ua:[`Прибери недоречні Catalog→provider та Identity→db.`,`Віднови бізнес-контракт Orders→Catalog.`,`Поясни власність таблиць у спільній фізичній базі.`]};var i=[{en:`Orders can check catalog availability via an explicit contract.`,ua:`Orders перевіряє наявність через явний контракт.`},{en:`Only Billing owns payment-provider calls.`,ua:`Лише Billing викликає платіжного провайдера.`}];var o={remove:[`orders->catalog`],add:[{from:`catalog`,to:`provider`,kind:`sync`,label:`Intentional defect / Навмисна помилка`},{from:`identity`,to:`db`,kind:`data`,label:`Intentional defect / Навмисна помилка`}]};var l={scenario:t,tasks:n,checks:i,mutations:o};export{i as checks,l as default,o as mutations,t as scenario,n as tasks};